@spec generators_spec  src=tests/specs/generators_spec.lua  loc=450  sha=872ec71  cases=28
@exercises generators (generators), tuning (tuning)
@surface   generators.retarget, tuning.findTemper, tuning.transposeStep, tuning.stepsBetween

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 9-11
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 14-17
      -- A slide host (pitch 60) and a ctx supplying the next same-lane note + pb ceiling.
  @fn slideHost(detune)  @ 18-20
  @fn triangle()  @ 24-30
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.

# Cases
  @case 'slide glides in: flat hold, slur to the interval, re-centre at the window end'  [pure]  @ 37-48
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 52-56
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 60-64
  @case 'slide.target='fixed' is a fixed-cents bend (cents demand, no next-note lookup)'  [pure]  @ 68-73
  @case 'slide.target='next' with no following note yields no delta (carrier untouched)'  [pure]  @ 77-81
  @case 'slide to a unison next note yields no delta (zero interval)'  [pure]  @ 85-89
  @case 'trill tiles the window from its start, alternating host pitch with the stepped note'  [pure]  @ 95-111
  @case 'trill carries host detune verbatim on the return (even) tiles'  [pure]  @ 115-122
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 128-133
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 137-152
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 158-163
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 167-175
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 179-184
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 188-194
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 198-205
  @case 'sine on a cc dest tiles the window with extrema in cc steps, anchored 0 at both ends'  [pure]  @ 211-224
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 230-245
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 249-259
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 265-277
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 281-290
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 294-305
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 311-334
  @case 'chord-stamp transposes by whole temper steps through ctx, not by raw pitch'  [pure]  @ 338-357
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 361-383
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 387-398
  @case 'lfo tiles the curve at 1/period QN, mapping each val by centre + scale, edges seeded'  [pure]  @ 404-421
  @case 'lfo clamps centre +/- scale to 0..127'  [pure]  @ 425-434
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 438-447

